#include <bits/stdc++.h>
using namespace std;
using LL = long long;

LL ncr[40][40];
LL ans[30][30];

int main() {
    // Fill Pascal's triangle for ncr
    for (int i = 0; i < 40; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j == 0 || j == i) ncr[i][j] = 1;
            else ncr[i][j] = ncr[i - 1][j - 1] + ncr[i - 1][j];
        }
    }

    // Initialize the ans array with predefined values
    // (values omitted for brevity, assume they are set as in original code)
    // ...

    LL R, C;
    cin >> R >> C;
    string str;
    cin >> str;
    LL n = R + C;
    LL blockarea[n][n];
    LL totalarea[n + 1][n + 1] = {0};
    for (LL a = 0; a < n; ++a) {
        for (LL b = 0; b < n; ++b) {
            blockarea[a][b] = ncr[a][R - 1] * ncr[b][R - 1];
        }
    }
    for (LL a = 1; a <= n; ++a) {
        for (LL b = 1; b <= n; ++b) {
            totalarea[a][b] = totalarea[a][b - 1] + totalarea[a - 1][b] - totalarea[a - 1][b - 1] + blockarea[a - 1][b - 1];
        }
    }
    LL revarea[n + 1][n + 1];
    for (LL a = 0; a <= n; ++a) {
        for (LL b = 0; b <= n; ++b) {
            revarea[a][b] = totalarea[n][n] - totalarea[n - a][n] - totalarea[n][n - b] + totalarea[n - a][n - b];
        }
    }

    LL d = min(2 * n - 1, n + R - 4);
    vector<map<LL, LL>> dp(n + 1), bp(n + 1);
    for (int i = 0; i <= n; ++i) {
        dp[i] = map<LL, LL>();
        bp[i] = map<LL, LL>();
    }
    dp[0][0] = 1;
    LL best = ans[R][C];
    LL m1 = (-best + totalarea[n][n]) / 2;
    LL m2 = totalarea[n][n] - m1;
    LL bestfreq = 0;

    for (LL x = 0; x <= n; ++x) {
        for (LL y = 0; y < n; ++y) {
            if (x + y + 1 <= d && str[x + y] != 'B') {
                for (auto &it : dp[x][y]) {
                    LL area2 = it.first + totalarea[n][y + 1] - totalarea[x][y + 1];
                    if (area2 > m2) continue;
                    dp[x][y + 1][it.first] += it.second;
                }
            }
            if (x + y + 1 <= 2 * n - d && str[n - x + n - y - 1] != 'B') {
                for (auto &it : bp[x][y]) {
                    LL area2 = totalarea[n][n] - it.first - totalarea[n - x][n - (y + 1)];
                    if (area2 > m2) continue;
                    bp[x][y + 1][it.first] += it.second;
                }
            }
        }
        if (x == n) continue;
        for (LL y = 0; y <= n; ++y) {
            if (x + y + 1 <= d && str[x + y] != 'A') {
                LL newarea = totalarea[x + 1][y] - totalarea[x][y];
                for (auto &it : dp[x][y]) {
                    LL c = it.first + newarea;
                    LL area2 = totalarea[x + 1][n] - c;
                    if (area2 > m2) continue;
                    dp[x + 1][y][it.first + newarea] += it.second;
                }
            }
            if (x + y + 1 <= 2 * n - d && str[n - x + n - y - 1] != 'A') {
                LL newarea = totalarea[n - x][n - y] - totalarea[n - x - 1][n - y];
                for (auto &it : bp[x][y]) {
                    if (it.first + newarea > m2) continue;
                    bp[x + 1][y][it.first + newarea] += it.second;
                }
            }
            if (x + y + 1 <= d) dp[x][y].clear();
            if (x + y + 1 <= 2 * n - d) bp[x][y].clear();
        }
    }

    for (LL x = 0; x <= n; ++x) {
        LL y = d - x;
        if (y < 0 || y > n) continue;
        for (auto &it : dp[x][y]) {
            LL c = it.first;
            LL freq = it.second;
            bestfreq += freq * bp[n - x][n - y][m1 - c];
            if (m1 != m2) bestfreq += freq * bp[n - x][n - y][m2 - c];
        }
    }

    cout << bestfreq << endl;
}
